def _get_calendar_events() -> list[tuple[str, int, set[str]]]:
    cal_path = os.environ.get("SYNTH_BENCHMARK_CALENDAR", "")
    if not cal_path:
        return []
    cached = _CALENDAR_CACHE.get(cal_path)
    if cached is not None:
        return cached
    p = Path(cal_path)
    if not p.exists():
        _CALENDAR_CACHE[cal_path] = []
        return []
    df = pd.read_parquet(p)
    dt = pd.to_datetime(df["time_utc"], utc=True)
    us_arr = [int(round(t.timestamp() * 1_000_000)) for t in dt]
    events_out: list[tuple[str, int, set[str]]] = []
    for ev, t_us, scope in zip(df["event"], us_arr, df["scope"]):
        scope_set = set(str(scope).split(","))
        events_out.append((str(ev), int(t_us), scope_set))
    _CALENDAR_CACHE[cal_path] = events_out
    return events_out


def _event_variance_multiplier(ts_us: np.ndarray, asset: str) -> np.ndarray:
    events = _get_calendar_events()
    if not events or ts_us.size == 0:
        return np.ones(ts_us.size, dtype=np.float64)
    t_min = int(ts_us[0]) - 7 * 3600_000_000
    t_max = int(ts_us[-1])
    mult = np.ones(ts_us.size, dtype=np.float64)
    for ev, ev_us, scope_set in events:
        if ev_us < t_min or ev_us > t_max:
            continue
        if "all" not in scope_set and asset not in scope_set:
            continue
        if ev == "FOMC":
            m_val = 2.10 if asset in SINGLE_EQUITY_ASSETS else (1.0 if asset == "WTIOIL" else 3.40)
            dur = 60 * 60_000_000
        elif ev == "NFP":
            m_val = 2.10 if (asset in CRYPTO_ASSETS or asset in {"XAU", "SP500"}) else 1.0
            dur = 30 * 60_000_000
        elif ev == "CPI":
            m_val = 1.80 if asset != "WTIOIL" else 1.0
            dur = 30 * 60_000_000
        elif ev == "EARNINGS":
            m_val = 12.0
            dur = 90 * 60_000_000
        elif ev == "NYSE_CLOSED":
            m_val = 0.25 if asset == "SP500" else 0.05
            dur = 390 * 60_000_000
        elif ev == "NYSE_EARLY_CLOSE":
            m_val = 0.30 if asset == "SP500" else 0.12
            dur = 120 * 60_000_000
        else:
            continue
        if m_val != 1.0:
            mask = (ts_us > ev_us) & (ts_us <= ev_us + dur)
            if np.any(mask):
                mult[mask] *= m_val
    return mult


def _stratified_normal_quantiles(half: int) -> np.ndarray:
    cached = _STRATIFIED_Z_CACHE.get(half)
    if cached is not None:
        return cached
    u = (np.arange(half, dtype=np.float64) + 0.5) / half
    a = np.array([
        -3.969683028665376e+01,  2.209460984245205e+02,
        -2.759285104469687e+02,  1.383577518672690e+02,
        -3.066479806614716e+01,  2.506628277459239e+00,
    ])
    b = np.array([
        -5.447609879822406e+01,  1.615858368580409e+02,
        -1.556989798598866e+02,  6.680131188771972e+01,
        -1.328068155288572e+01,
    ])
    c = np.array([
        -7.784894002430293e-03, -3.223964580411365e-01,
        -2.400758277161838e+00, -2.549732539343734e+00,
         4.374664141464968e+00,  2.938163982698783e+00,
    ])
    d = np.array([
         7.784695709041462e-03,  3.224671290700398e-01,
         2.445134137142996e+00,  3.754408661907416e+00,
    ])
    p_low = 0.02425
    p_high = 1.0 - p_low
    q_out = np.empty_like(u)
    low = u < p_low
    high = u > p_high
    mid = ~(low | high)
    if np.any(low):
        q = np.sqrt(-2.0 * np.log(u[low]))
        q_out[low] = (((((c[0]*q + c[1])*q + c[2])*q + c[3])*q + c[4])*q + c[5]) / (
            (((d[0]*q + d[1])*q + d[2])*q + d[3])*q + 1.0
        )
    if np.any(mid):
        q = u[mid] - 0.5
        r = q * q
        q_out[mid] = (((((a[0]*r + a[1])*r + a[2])*r + a[3])*r + a[4])*r + a[5])*q / (
            ((((b[0]*r + b[1])*r + b[2])*r + b[3])*r + b[4])*r + 1.0
        )
    if np.any(high):
        q = np.sqrt(-2.0 * np.log(1.0 - u[high]))
        q_out[high] = -(((((c[0]*q + c[1])*q + c[2])*q + c[3])*q + c[4])*q + c[5]) / (
            (((d[0]*q + d[1])*q + d[2])*q + d[3])*q + 1.0
        )
    _STRATIFIED_Z_CACHE[half] = q_out
    return q_out


def _make_rng(asset: str, start_time, time_length: int) -> np.random.Generator:
    seed_env = os.environ.get("SYNTH_BENCHMARK_SEED")
    base_seed = int(seed_env) if seed_env is not None else 20261021
    random.seed(base_seed)
    np.random.seed(base_seed & 0xFFFFFFFF)
    h = hashlib.blake2b(f"{base_seed}:{asset}:{start_time}:{time_length}".encode(), digest_size=8).digest()
    prompt_seed = int.from_bytes(h, "little")
    return np.random.default_rng(prompt_seed)


def _slots_from_utc_us(ts_us: np.ndarray) -> np.ndarray:
    total_mins = ts_us // 60_000_000
    min_of_week = (total_mins + 3 * 1440) % 10080
    return (min_of_week // 30).astype(np.int64)


def _subslot_modulation(ts_us: np.ndarray, asset: str, is_1h: bool) -> np.ndarray:
    if is_1h:
        moh_tab = _MOH_S2.get(asset)
        if moh_tab is None:
            return np.ones(ts_us.size, dtype=np.float64)
        moh = ((ts_us // 60_000_000) % 60).astype(np.int64)
        return moh_tab[moh]
    sub_tab = _SUB288_S2.get(asset)
    if sub_tab is None:
        return np.ones(ts_us.size, dtype=np.float64)
    total_mins = ts_us // 60_000_000
    min_of_week = (total_mins + 3 * 1440) % 10080
    is_wk = (min_of_week // 1440) < 5
    slot288 = ((min_of_week % 1440) // 5).astype(np.int64)
    return np.where(is_wk, sub_tab[slot288], 1.0)


def _timestamp_to_utc_us(ts) -> int:
    t = pd.Timestamp(ts)
    if t.tzinfo is None:
        t = t.tz_localize("UTC")
    else:
        t = t.tz_convert("UTC")
    return int(round(t.timestamp() * 1_000_000))


def _index_to_utc_us(idx: pd.Index) -> np.ndarray:
    if isinstance(idx, pd.DatetimeIndex):
        if idx.tz is None:
            return idx.tz_localize("UTC").as_unit("us").asi8
        return idx.tz_convert("UTC").as_unit("us").asi8
    dt = pd.to_datetime(idx, utc=True)
    return dt.as_unit("us").asi8


def _distribution_params(asset: str, time_length: int) -> tuple[float, float, float]:
    if time_length <= 3600:
        return PARAMS_1H
    if asset in CRYPTO_ASSETS:
        return PARAMS_CRYPTO_24H
    if asset in SINGLE_EQUITY_ASSETS:
        return PARAMS_EQUITY_24H
    return PARAMS_MACRO_24H


def _compute_5m_mad_ewma(
    valid_pos: np.ndarray,
    rets: np.ndarray,
    grid_us: np.ndarray,
    gs2: np.ndarray,
) -> np.ndarray | None:
    start_idx = int(valid_pos[0])
    n_active = len(grid_us) - start_idx
    n_blocks = n_active // 5
    if n_blocks < 10:
        return None
    trim_start = len(grid_us) - n_blocks * 5
    ret_pos = valid_pos[1:]
    in_range = ret_pos >= trim_start
    b_idx = np.clip(((ret_pos[in_range] - trim_start) // 5).astype(np.int64), 0, n_blocks - 1)
    r5_blk = np.bincount(b_idx, weights=rets[in_range], minlength=n_blocks)
    s2_blk = np.maximum(gs2[trim_start:].reshape(n_blocks, 5).sum(axis=1), 1e-4)
    rate5 = (r5_blk ** 2) / s2_blk
    pos5 = rate5[rate5 > 0]
    cap5 = float(np.percentile(pos5, 98.5)) if pos5.size > 10 else 1.0
    r5_abs_win = np.minimum(np.abs(r5_blk), np.sqrt(cap5 * s2_blk))
    mad_num_blk = 1.2533141373155001 * r5_abs_win * np.sqrt(s2_blk)
    age_blk_min = (np.arange(n_blocks - 1, -1, -1, dtype=np.float64) + 0.5) * 5.0
    ew_mad5 = np.empty(len(EWMA_LAMBDAS_6), dtype=np.float64)
    for i, lam in enumerate(EWMA_LAMBDAS_6):
        w = np.exp(-lam * age_blk_min)
        ew_mad5[i] = max(float(np.dot(w, mad_num_blk)) / max(float(np.dot(w, s2_blk)), 1e-6), 1e-6)
    return np.log(np.maximum(ew_mad5, 1e-6))


def _compute_ohlc_log_ewma(
    context_prices,
    g_slice: slice,
    age_grid_min: np.ndarray,
    s2_grid_active: np.ndarray,
    anchor_log_sigma: float,
) -> np.ndarray | None:
    if not isinstance(context_prices, pd.DataFrame):
        return None
    if "high" not in context_prices.columns or "low" not in context_prices.columns:
        return None
    hi = context_prices["high"].to_numpy(dtype=np.float64)[g_slice]
    lo = context_prices["low"].to_numpy(dtype=np.float64)[g_slice]
    cl = context_prices["close"].to_numpy(dtype=np.float64)[g_slice]
    ok = np.isfinite(hi) & np.isfinite(lo) & np.isfinite(cl) & (lo > 0.0) & (hi >= lo)
    if int(np.sum(ok)) < 20:
        return None
    ok_idx = np.flatnonzero(ok)
    c_ok = cl[ok_idx]
    h_ok = hi[ok_idx].copy()
    l_ok = lo[ok_idx].copy()
    consec = np.diff(ok_idx) == 1
    c_prev = c_ok[:-1][consec]
    h_ok[1:][consec] = np.maximum(h_ok[1:][consec], c_prev)
    l_ok[1:][consec] = np.minimum(l_ok[1:][consec], c_prev)
    hl_r2 = (np.log(h_ok / l_ok) ** 2) / 2.772588722239781
    s2_ok = np.maximum(s2_grid_active[ok_idx], 1e-4)
    hl_rate = hl_r2 / s2_ok
    pos_hl = hl_rate[hl_rate > 0.0]
    if pos_hl.size > 10:
        hl_r2 = np.minimum(hl_rate, float(np.percentile(pos_hl, 98.5))) * s2_ok
    ew_hl = np.empty(len(EWMA_LAMBDAS_6), dtype=np.float64)
    age_ok = age_grid_min[ok_idx]
    for i, lam in enumerate(EWMA_LAMBDAS_6):
        w = np.exp(-lam * age_ok)
        ew_hl[i] = np.sqrt(max(float(np.dot(w, hl_r2)) / max(float(np.dot(w, s2_ok)), 1e-6), 1e-12))
    le_hl = np.log(np.maximum(ew_hl, 1e-6))
    return le_hl - le_hl[5] + anchor_log_sigma


def _apply_secant_shocks(
    shocks_inc: np.ndarray,
    eta_tot: float,
    eta_blk: float = 1.0,
    n_blks: int = 8,
    eta_sub: float = 1.0,
    n_sub: int = 48,
) -> np.ndarray:
    out = shocks_inc
    if abs(eta_sub - 1.0) > 1e-6 and out.shape[1] >= n_sub:
        s_len = out.shape[1] // n_sub
        out = out.copy()
        for s in range(n_sub):
            sl = slice(s * s_len, (s + 1) * s_len)
            sub = out[:, sl]
            s2 = np.var(sub, axis=0)
            w = s2 / max(float(np.sum(s2)), 1e-12)
            s_sum = np.sum(sub, axis=1, keepdims=True)
            out[:, sl] = sub + (eta_sub - 1.0) * s_sum * w[None, :]
    eff_blk = eta_blk / eta_sub if eta_sub != 0.0 else eta_blk
    if abs(eff_blk - 1.0) > 1e-6 and out.shape[1] >= n_blks:
        b_len = out.shape[1] // n_blks
        if out is shocks_inc:
            out = out.copy()
        for b in range(n_blks):
            sl = slice(b * b_len, (b + 1) * b_len)
            sub = out[:, sl]
            s2 = np.var(sub, axis=0)
            w = s2 / max(float(np.sum(s2)), 1e-12)
            b_sum = np.sum(sub, axis=1, keepdims=True)
            out[:, sl] = sub + (eff_blk - 1.0) * b_sum * w[None, :]
    eff_tot = eta_tot / eta_blk if eta_blk != 0.0 else eta_tot
    if abs(eff_tot - 1.0) > 1e-6:
        s2 = np.var(out, axis=0)
        w = s2 / max(float(np.sum(s2)), 1e-12)
        t_sum = np.sum(out, axis=1, keepdims=True)
        out = out + (eff_tot - 1.0) * t_sum * w[None, :]
    return out


def simulate(
    asset: str,
    start_time,
    time_increment: int = 300,
    time_length: int = 86_400,
    num_simulations: int = 1000,
    context_prices=None,
):
    rng = _make_rng(asset, start_time, time_length)
    steps = time_length // time_increment + 1
    n_inc = steps - 1
    step_mins = max(time_increment // 60, 1)
    is_1h = time_length <= 3600

    if isinstance(context_prices, pd.DataFrame):
        close_series = context_prices["close"]
        full_idx = context_prices.index
    else:
        close_series = context_prices
        full_idx = close_series.index

    vals = close_series.to_numpy(dtype=np.float64)
    valid_pos = np.flatnonzero(np.isfinite(vals))
    if valid_pos.size == 0:
        last = 1.0
    else:
        last = float(vals[valid_pos[-1]])

    s2_back = _S2_BACK_336.get(asset, _DEFAULT_S2_336)
    if is_1h:
        s2_f_raw = _S2_FWD_336.get(asset, s2_back)
        s2_f_norm = s2_f_raw / np.mean(s2_f_raw)
        s2_btc_raw = _S2_FWD_336.get("BTC", s2_back)
        s2_btc_norm = s2_btc_raw / np.mean(s2_btc_raw)
        s2_fwd = 0.35 * s2_back + 0.45 * s2_f_norm + 0.20 * s2_btc_norm
    else:
        s2_fwd = _S2_FWD_336.get(asset, s2_back)
        if asset in CRYPTO_ASSETS and float(np.mean(s2_fwd[240:])) > 0.70 * float(np.mean(s2_fwd[:240])):
            s2_fwd = s2_fwd.copy()
            s2_fwd[240:288] *= 0.94
    lt_sigma = LONG_TERM_SIGMA_1M.get(asset, 5e-4)

    start_us = _timestamp_to_utc_us(start_time)
    fwd_min_offsets = np.arange(1, n_inc * step_mins + 1, dtype=np.int64)
    fwd_us = start_us + fwd_min_offsets * 60_000_000
    fwd_slots = _slots_from_utc_us(fwd_us)
    fwd_s2_min = (
        s2_fwd[fwd_slots]
        * _subslot_modulation(fwd_us, asset, is_1h)
        * _event_variance_multiplier(fwd_us, asset)
    )
    fwd_s2 = fwd_s2_min.reshape(n_inc, step_mins).sum(axis=1)
    step_seas_sqrt = np.sqrt(np.maximum(fwd_s2, 1e-4))
    s2_fwd_mean = float(np.mean(fwd_s2_min))

    brk_mult = 1.0
    if valid_pos.size > 10:
        grid_us = _index_to_utc_us(full_idx)
        grid_slots = _slots_from_utc_us(grid_us)
        grid_s2 = (
            s2_back[grid_slots]
            * _subslot_modulation(grid_us, asset, is_1h)
            * _event_variance_multiplier(grid_us, asset)
        )
        grid_s2_cumsum = np.concatenate(([0.0], np.cumsum(grid_s2)))

        valid_vals = vals[valid_pos]
        rets = np.diff(np.log(valid_vals))
        finite = np.isfinite(rets)
        if not np.all(finite):
            rets = np.where(finite, rets, 0.0)

        ds2 = grid_s2_cumsum[valid_pos[1:] + 1] - grid_s2_cumsum[valid_pos[:-1] + 1]
        ds2 = np.maximum(ds2, 1e-4)

        rate_ds = (rets ** 2) / ds2
        pos_rates = rate_ds[rate_ds > 0]
        if pos_rates.size > 10:
            cap_ds = float(np.percentile(pos_rates, 98.5))
            r2_win = np.minimum(rate_ds, cap_ds) * ds2
        else:
            r2_win = rets ** 2

        r1_scaled = 1.2533141373155001 * np.abs(rets) * np.sqrt(ds2)

        t_end_us = int(grid_us[-1])
        valid_us = grid_us[valid_pos]
        t_mid_us = 0.5 * (valid_us[1:] + valid_us[:-1])
        age_bar_min = np.maximum((t_end_us - t_mid_us) / 60_000_000.0, 0.0)

        g_slice = slice(int(valid_pos[0]), len(grid_us))
        age_grid_min = np.maximum((t_end_us - grid_us[g_slice]) / 60_000_000.0, 0.0)
        s2_grid_active = grid_s2[g_slice]

        ewma_l2 = np.empty(len(EWMA_LAMBDAS_6), dtype=np.float64)
        ewma_l1 = np.empty(len(EWMA_LAMBDAS_6), dtype=np.float64)
        s2_bar_k = np.empty(len(EWMA_LAMBDAS_6), dtype=np.float64)
        for i, lam in enumerate(EWMA_LAMBDAS_6):
            w_bar = np.exp(-lam * age_bar_min)
            w_grid = np.exp(-lam * age_grid_min)
            den = max(float(np.dot(w_grid, s2_grid_active)), 1e-6)
            s2_bar_k[i] = den / max(float(np.sum(w_grid)), 1e-6)
            ewma_l2[i] = np.sqrt(max(float(np.dot(w_bar, r2_win)) / den, 1e-12))
            ewma_l1[i] = max(float(np.dot(w_bar, r1_scaled)) / den, 1e-6)

        log_l2 = np.log(np.maximum(ewma_l2, 1e-6))
        log_l1 = np.log(np.maximum(ewma_l1, 1e-6))
        log_mad5 = _compute_5m_mad_ewma(valid_pos, rets, grid_us, grid_s2)
        if log_mad5 is None:
            log_mad5 = log_l2
        log_hl = _compute_ohlc_log_ewma(context_prices, g_slice, age_grid_min, s2_grid_active, float(log_l2[5]))
        if log_hl is None:
            log_hl = log_l2

        if is_1h:
            log_ewma = 0.45 * log_l2 + 0.20 * log_l1 + 0.20 * log_mad5 + 0.15 * log_hl
            sigma_short = float(np.exp(np.dot(WEIGHTS_1H_START, log_ewma)))
            sigma_long = float(np.exp(np.dot(WEIGHTS_1H_END, log_ewma)))
        else:
            if asset in CRYPTO_ASSETS:
                log_ewma = 0.80 * log_l2 + 0.20 * (log_l1 + 0.20)
            else:
                if asset == "XAU":
                    log_ewma = 0.82 * log_l2 + 0.18 * (log_mad5 + 0.05)
                else:
                    log_ewma = 0.55 * log_l2 + 0.15 * (log_l1 + 0.05) + 0.22 * (log_mad5 + 0.05) + 0.08 * log_hl
                if asset in {"XAU", "WTIOIL", "GOOGLX", "TSLAX", "SPCX", "SP500"}:
                    alpha_k = np.minimum(s2_bar_k / max(s2_fwd_mean, 0.1), 1.0)
                    diff_k = log_ewma - log_ewma[5]
                    log_ewma = np.where(diff_k < 0.0, log_ewma[5] + (0.5 + 0.5 * alpha_k) * diff_k, log_ewma)
            w_long = WEIGHTS_24H_LONG
            p_w = 0.10
            sigma_short = float(np.exp(np.dot(WEIGHTS_24H_SHORT, log_ewma)))
            sigma_long_ctx = float(np.exp(np.dot(w_long, log_ewma)))
            sigma_long = float(
                np.exp((1.0 - p_w) * np.log(sigma_long_ctx) + p_w * np.log(lt_sigma))
            )
            if asset in CRYPTO_ASSETS and len(vals) >= 1440:
                idx_24h = int(np.searchsorted(valid_pos, max(0, len(vals) - 1440)))
                rv_24h = float(np.sqrt(np.sum(rets[idx_24h:] ** 2)))
                er_24h = abs(float(np.log(vals[valid_pos[-1]] / vals[valid_pos[idx_24h]]))) / max(rv_24h, 1e-6)
                if er_24h < 0.35:
                    brk_mult = 1.0 - 0.06 * (0.35 - er_24h)
                elif er_24h > 0.55 and sigma_short > sigma_long:
                    brk_mult = 1.0 + 0.05 * min(er_24h - 0.55, 0.45)
    else:
        sigma_short = lt_sigma
        sigma_long = lt_sigma

    c_scale, sig_path_vv, sig_step_vv = _distribution_params(asset, time_length)

    mid_lead_mins = (np.arange(n_inc, dtype=np.float64) + 0.5) * step_mins
    rev_tau = REVERSION_TAU_1H if is_1h else REVERSION_TAU_24H
    decay = np.exp(-mid_lead_mins / rev_tau)
    sigma_base_t = sigma_long * ((sigma_short / max(sigma_long, 1e-8)) ** decay)

    per_step_sigma = (c_scale * brk_mult * sigma_base_t) * step_seas_sqrt

    half = num_simulations // 2
    if half > 0:
        eps = rng.standard_normal((half, n_inc))
        if sig_step_vv > 0.0:
            eta = rng.standard_normal((half, n_inc))
            eps = eps * np.exp(sig_step_vv * eta - 0.5 * sig_step_vv * sig_step_vv)
        z_step = np.vstack([eps, -eps])
        col_std = np.std(z_step, axis=0, keepdims=True)
        eps = eps / np.where(col_std > 1e-8, col_std, 1.0)
        if sig_path_vv > 0.0:
            q_z = _stratified_normal_quantiles(half)
            m_half = np.exp(sig_path_vv * q_z - 0.5 * sig_path_vv * sig_path_vv)[:, None]
            m_rms = float(np.sqrt(np.mean(m_half ** 2)))
            eps = eps * (m_half / m_rms)
        if num_simulations % 2 == 1:
            z_extra = rng.standard_normal((1, n_inc))
            z = np.vstack([eps, -eps, z_extra])
        else:
            z = np.vstack([eps, -eps])
    else:
        z = rng.standard_normal((num_simulations, n_inc))

    shocks_inc = z * per_step_sigma[None, :]
    if is_1h:
        if asset != "ETH":
            shocks_inc = _apply_secant_shocks(shocks_inc, eta_tot=0.95, eta_blk=0.95, n_blks=4)
    elif asset in CRYPTO_ASSETS:
        if asset in {"BTC", "ETH"}:
            shocks_inc = _apply_secant_shocks(shocks_inc, eta_tot=1.00, eta_blk=0.95, n_blks=8, eta_sub=0.97, n_sub=48)
    else:
        eta_equ = 1.05 if asset == "SPCX" else 1.09
        shocks_inc = _apply_secant_shocks(shocks_inc, eta_tot=eta_equ, eta_blk=1.0, n_blks=8)

    shocks = np.empty((num_simulations, steps), dtype=np.float64)
    shocks[:, 0] = 0.0
    shocks[:, 1:] = shocks_inc
    paths = last * np.exp(np.cumsum(shocks, axis=1))
    return (start_time, time_increment, *[p.tolist() for p in paths])
